{
    "水溪市": {
        "城市概况": {
            "地理位置": "中国南方沿海城市",
            "城市特色": "现代化与传统文化并存的新兴城市",
            "气候特征": "亚热带季风气候，四季分明，雨量充沛"
        },
        "主要地区": {
            "水溪大学周边": {
                "商业街": "以年轻人文化为主的商业区，有许多小吃店、奶茶店、livehouse等",
                "居民区": "学生公寓、教师公寓为主的生活区",
                "文化设施": "图书馆、博物馆、音乐厅等"
            },
            "市中心": {
                "商圈": "高端商场、写字楼集中地",
                "娱乐区": "酒吧街、KTV、电影院等",
                "文创园": {
                    "特色": "年轻艺术家聚集地",
                    "设施": {
                        "Crucifix训练室": {
                            "位置": "距离水溪大学约15分钟车程",
                            "设施": {
                                "主训练室": {
                                    "面积": "约80平方米",
                                    "设备": "专业架子鼓、吉他、贝斯、键盘等乐器",
                                    "隔音": "专业级隔音设施"
                                },
                                "休息室": "约30平方米，配备沙发、饮水机、小冰箱",
                                "录音室": "约20平方米，专业录音设备"
                            }
                        },
                        "其他工作室": "独立音乐人工作室、画室等"
                    }
                }
            },
            "滨海区": {
                "特色": "现代化海滨景观带",
                "设施": "海滨公园、音乐喷泉、沙滩等",
                "活动": "经常举办露天音乐会和文化活动"
            }
        }
    },
    "水溪大学": {
        "学校概况": {
            "类型": "985、211工程重点大学",
            "排名": "全国前30名",
            "校区": "占地面积约3000亩",
            "学科特色": {
                "优势学科": [
                    "音乐表演",
                    "计算机科学",
                    "生物工程",
                    "新闻传媒",
                    "建筑设计"
                ],
                "重点实验室": [
                    "人工智能国家重点实验室",
                    "生物医药研究中心",
                    "现代传媒技术研究所"
                ]
            }
        },
        "校园设施": {
            "教学区": {
                "音乐楼": {
                    "位置": "校园东部",
                    "特色": "设有专业录音棚、排练室",
                    "使用": "Crucifix乐队经常在这里排练"
                },
                "艺术楼": "设有画室、展览厅等",
                "传媒楼": "设有演播厅、编辑部等"
            },
            "生活区": {
                "学生宿舍": "分布在校园南部，环境宜人",
                "食堂": "共有4个食堂，提供多样化美食",
                "运动设施": "体育馆、操场、游泳池等"
            },
            "文化设施": {
                "图书馆": "藏书丰富，环境安静",
                "学生活动中心": "社团活动场所",
                "小剧场": "学生表演场地"
            }
        }
    }
}
